// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
  Easing,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

// Module-level font loading
const { fontFamily: interFamily } = loadInter();



export type AppStoreSearchProps = Record<string, any>;

const AppStoreSearch: React.FC<AppStoreSearchProps> = ({
  backgroundColor = "#F2F2F7",
  transparentBackground = false,
  durationInSeconds = 6,
  searchQuery = "KUDOS",
  headingText = "Search",
  primaryAccentColor = "#007AFF",
  searchBarColor = "#E3E3E8",
  textColor = "#000000",
  secondaryTextColor = "#8E8E93",
  results = [
    "Kudos",
    "Kudos: Track Team Praise",
    "Kudos Rewards App",
    "Kudos for Work",
  ],
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Parse logic
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Layout calculations
  const containerWidth = width * 0.45;
  const maxContainerWidth = 800;
  const actualContainerWidth = Math.min(containerWidth, maxContainerWidth);
  const leftPadding = (width - actualContainerWidth) / 2;

  // Timeline
  const introEnd = 20;
  const focusStart = introEnd + 10;
  const typingStart = focusStart + 15;
  const typingFramesPerChar = 4;
  const typingDuration = searchQuery.length * typingFramesPerChar;
  const typingEnd = typingStart + typingDuration;
  const searchExecute = typingEnd + 20;

  // 1. Intro Animations (Heading and Search Bar fade in)
  const introY = interpolate(frame, [0, introEnd], [40, 0], {
    easing: Easing.out(Easing.exp),
    extrapolateRight: "clamp",
  });
  const introOpacity = interpolate(frame, [0, introEnd], [0, 1], {
    extrapolateRight: "clamp",
  });

  // 2. Focus Animation (Cancel button appears, bar shrinks)
  const focusProgress = spring({
    frame: frame - focusStart,
    fps,
    config: { damping: 14, stiffness: 120 },
  });
  const cancelWidth = 80;
  const searchBarWidth = interpolate(
    focusProgress,
    [0, 1],
    [actualContainerWidth, actualContainerWidth - cancelWidth]
  );
  const cancelOpacity = interpolate(focusProgress, [0, 0.5, 1], [0, 0, 1]);
  const cancelX = interpolate(focusProgress, [0, 1], [20, 0]);

  // 3. Typing Animation
  const charsToShow = Math.floor(
    interpolate(frame, [typingStart, typingEnd], [0, searchQuery.length], {
      extrapolateRight: "clamp",
      extrapolateLeft: "clamp",
    })
  );
  const currentText = searchQuery.slice(0, charsToShow);

  // 4. Cursor Blink
  const showCursor =
    frame >= focusStart &&
    frame < searchExecute &&
    Math.floor(frame / 15) % 2 === 0;

  // 5. Search Execution (Cancel fades, results appear)
  const isExecuting = frame >= searchExecute;
  const executeProgress = spring({
    frame: frame - searchExecute,
    fps,
    config: { damping: 14, stiffness: 120 },
  });
  
  // Re-expand search bar on execute (simulating dismiss keyboard/cancel focus)
  const finalSearchBarWidth = interpolate(
    executeProgress,
    [0, 1],
    [actualContainerWidth - cancelWidth, actualContainerWidth]
  );
  const finalCancelOpacity = interpolate(executeProgress, [0, 1], [1, 0]);

  const activeBarWidth = isExecuting ? finalSearchBarWidth : searchBarWidth;
  const activeCancelOpacity = isExecuting ? finalCancelOpacity : cancelOpacity;

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: interFamily,
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        justifyContent: "center",
        overflow: "hidden",
      }}
    >
      <div
        style={{
          width: actualContainerWidth,
          height: height * 0.8,
          display: "flex",
          flexDirection: "column",
          position: "relative",
          transform: `translateY(${introY}px)`,
          opacity: introOpacity,
        }}
      >
        {/* Header */}
        <div style={{ marginBottom: 24 }}>
          <h1
            style={{
              fontSize: 64,
              fontWeight: 800,
              color: textColor,
              margin: 0,
              letterSpacing: "-0.03em",
            }}
          >
            {headingText}
          </h1>
        </div>

        {/* Search Bar Row */}
        <div
          style={{
            display: "flex",
            alignItems: "center",
            width: actualContainerWidth,
            position: "relative",
            marginBottom: 32,
          }}
        >
          {/* Search Input Container */}
          <div
            style={{
              width: activeBarWidth,
              height: 72,
              backgroundColor: searchBarColor,
              borderRadius: 20,
              display: "flex",
              alignItems: "center",
              padding: "0 20px",
              boxSizing: "border-box",
            }}
          >
            {/* Search Icon */}
            <svg
              width="24"
              height="24"
              viewBox="0 0 24 24"
              fill="none"
              stroke={secondaryTextColor}
              strokeWidth="2.5"
              strokeLinecap="round"
              strokeLinejoin="round"
              style={{ marginRight: 12, minWidth: 24 }}
            >
              <circle cx="11" cy="11" r="8"></circle>
              <line x1="21" y1="21" x2="16.65" y2="16.65"></line>
            </svg>

            {/* Text & Cursor */}
            <div
              style={{
                display: "flex",
                alignItems: "center",
                flex: 1,
                position: "relative",
                overflow: "hidden",
              }}
            >
              <span
                style={{
                  fontSize: 28,
                  color: textColor,
                  whiteSpace: "pre",
                  lineHeight: 1,
                }}
              >
                {currentText}
              </span>
              {/* Placeholder text */}
              {charsToShow === 0 && !isExecuting && (
                <span
                  style={{
                    position: "absolute",
                    fontSize: 28,
                    color: secondaryTextColor,
                    pointerEvents: "none",
                  }}
                >
                  Games, Apps, Stories and More
                </span>
              )}
              {/* Cursor */}
              <div
                style={{
                  width: 3,
                  height: 32,
                  backgroundColor: primaryAccentColor,
                  opacity: showCursor ? 1 : 0,
                  marginLeft: 2,
                  borderRadius: 2,
                }}
              />
            </div>

            {/* Clear Button (X) */}
            {charsToShow > 0 && !isExecuting && (
              <div
                style={{
                  width: 24,
                  height: 24,
                  borderRadius: "50%",
                  backgroundColor: secondaryTextColor,
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  marginLeft: 12,
                  opacity: interpolate(
                    frame,
                    [typingStart, typingStart + 5],
                    [0, 1],
                    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
                  ),
                }}
              >
                <svg
                  width="14"
                  height="14"
                  viewBox="0 0 24 24"
                  fill="none"
                  stroke={searchBarColor}
                  strokeWidth="3"
                  strokeLinecap="round"
                  strokeLinejoin="round"
                >
                  <line x1="18" y1="6" x2="6" y2="18"></line>
                  <line x1="6" y1="6" x2="18" y2="18"></line>
                </svg>
              </div>
            )}
          </div>

          {/* Cancel Button */}
          <div
            style={{
              position: "absolute",
              right: 0,
              opacity: activeCancelOpacity,
              transform: `translateX(${isExecuting ? 0 : cancelX}px)`,
              width: cancelWidth,
              display: "flex",
              justifyContent: "flex-end",
              alignItems: "center",
            }}
          >
            <span
              style={{
                fontSize: 24,
                color: primaryAccentColor,
                fontWeight: 500,
              }}
            >
              Cancel
            </span>
          </div>
        </div>

        {/* Results List */}
        <div
          style={{
            display: "flex",
            flexDirection: "column",
            width: "100%",
            gap: 20,
          }}
        >
          {results.map((result, index) => {
            const itemDelay = searchExecute + 5 + index * 4;
            const itemProgress = spring({
              frame: frame - itemDelay,
              fps,
              config: { damping: 12, stiffness: 100 },
            });

            const itemY = interpolate(itemProgress, [0, 1], [40, 0]);
            const itemOpacity = interpolate(itemProgress, [0, 1], [0, 1]);

            // Colors for app icons to look varied but deterministic
            const hue = (index * 45 + 210) % 360;
            const iconBg = `hsl(${hue}, 80%, 60%)`;

            return (
              <div
                key={index}
                style={{
                  display: "flex",
                  flexDirection: "row",
                  alignItems: "center",
                  padding: "16px 0",
                  borderBottom: `1px solid ${secondaryTextColor}33`,
                  transform: `translateY(${itemY}px)`,
                  opacity: itemOpacity,
                }}
              >
                {/* App Icon */}
                <div
                  style={{
                    width: 80,
                    height: 80,
                    backgroundColor: iconBg,
                    borderRadius: 18,
                    marginRight: 20,
                    boxShadow: "0 4px 12px rgba(0,0,0,0.1)",
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "center",
                  }}
                >
                  <span style={{ color: "white", fontSize: 32, fontWeight: 800 }}>
                    {result.charAt(0)}
                  </span>
                </div>

                {/* App Info */}
                <div style={{ flex: 1, display: "flex", flexDirection: "column" }}>
                  <h3
                    style={{
                      margin: 0,
                      fontSize: 24,
                      fontWeight: 600,
                      color: textColor,
                      marginBottom: 4,
                    }}
                  >
                    {result}
                  </h3>
                  <p
                    style={{
                      margin: 0,
                      fontSize: 18,
                      color: secondaryTextColor,
                    }}
                  >
                    {index === 0 ? "The Official App" : "Productivity"}
                  </p>
                </div>

                {/* GET Button */}
                <div
                  style={{
                    padding: "8px 24px",
                    backgroundColor: `${primaryAccentColor}1A`, // 10% opacity
                    borderRadius: 20,
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "center",
                  }}
                >
                  <span
                    style={{
                      color: primaryAccentColor,
                      fontSize: 20,
                      fontWeight: 700,
                    }}
                  >
                    GET
                  </span>
                </div>
              </div>
            );
          })}
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default AppStoreSearch;